module.exports="\"];\nfor(let i=1;i<=PATTERN_COUNT;i++){const img=new Image();img.onload=()=>{patternImages[i]=img;for(const w of ['kit','short'])if(state[w])renderPatterns(w)};img.src=PATTERN_SOURCES[i-1]}\nfunction patternMask(which,key){const c=cached[which];if(!c)return null;\n if(which==='kit')return key==='dominant'?c.dominantMask:key==='shoulders'?c.shoulderMask:key==='secondary'?c.chestMask:null;\n if(key==='secondary')return c.sideMask;\n if(key==='dominant' && c.pixels){\n  if(c.patternDominantMask)return c.patternDominantMask;\n  const a=c.pixels.data,side=c.sideMask,out=new Uint8ClampedArray(a.length);\n  for(let i=0;i<a.length;i+=4){\n   if(a[i+3]>55 && Math.min(a[i],a[i+1],a[i+2])<221 && !(side&&side[i+3]>55)){\n    out[i]=255;out[i+1]=255;out[i+2]=255;out[i+3]=255;\n   }\n  }\n  c.patternDominantMask=out;return out;\n }\n return null;\n}\nfunction ensurePatternCanvas(which){if(patternCanvases[which])return patternCanvases[which];\n const base=document.getElementById(which+'Canvas'),c=document.createElement('canvas');c.width=1598;c.height=1169;c.className='pattern-art';if(which==='short')c.style.transform='translateX(-2.816%)';base.after(c);patternCanvases[which]=c;return c;\n}\n// The two garment views use independently centered copies of one source pattern.\n// Keep the same square size for both views; only positioning differs.\nconst patternEdgeCache={};\nfunction insetPatternAlpha(which,key,mask,w,h){\n const cacheKey=which+':'+key;\n if(patternEdgeCache[cacheKey])return patternEdgeCache[cacheKey];\n // Inner fade across every panel: no pattern ink outside the existing panel mask.\n // Two-pass distance transform keeps the larger feather efficient on mobile.\n const fade=key==='dominant'?14:11, n=w*h;\n const dist=new Uint8Array(n),out=new Uint8Array(n);\n for(let i=0;i<n;i++)dist[i]=mask[i*4+3]>100?255:0;\n for(let y=0;y<h;y++)for(let x=0;x<w;x++){\n  const i=y*w+x;if(!dist[i])continue;\n  let d=(x===0||y===0)?1:255;\n  if(x>0)d=Math.min(d,dist[i-1]+1);\n  if(y>0)d=Math.min(d,dist[i-w]+1);\n  if(x>0&&y>0)d=Math.min(d,dist[i-w-1]+1);\n  if(x+1<w&&y>0)d=Math.min(d,dist[i-w+1]+1);\n  dist[i]=d;\n }\n for(let y=h-1;y>=0;y--)for(let x=w-1;x>=0;x--){\n  const i=y*w+x;if(!dist[i])continue;\n  let d=(x===w-1||y===h-1)?Math.min(dist[i],1):dist[i];\n  if(x+1<w)d=Math.min(d,dist[i+1]+1);\n  if(y+1<h)d=Math.min(d,dist[i+w]+1);\n  if(x+1<w&&y+1<h)d=Math.min(d,dist[i+w+1]+1);\n  if(x>0&&y+1<h)d=Math.min(d,dist[i+w-1]+1);\n  dist[i]=d;\n }\n for(let i=0;i<n;i++){\n  if(!dist[i])continue;\n  const t=Math.max(0,Math.min(1,(dist[i]-1)/fade));\n  out[i]=Math.round(255*t*t*(3-2*t));\n }\n patternEdgeCache[cacheKey]=out;return out;\n}\nfunction applyHalfMoonExclusion(alphaArr,which,key,w,h){\n if(which!=='kit'||key!=='dominant')return alphaArr;\n const out=new Uint8Array(alphaArr);\n const cx=Math.round(w*0.755),cy=58,rx=96,ry=42;\n for(let y=Math.max(0,cy-ry);y<Math.min(h,cy+ry+1);y++)for(let x=Math.max(0,Math.round(cx-rx));x<Math.min(w,Math.round(cx+rx+1));x++){\n  const nx=(x-cx)/rx,ny=(y-cy)/ry;\n  if(nx*nx+ny*ny<=1 && y<=cy+ry){out[y*w+x]=0;}\n }\n return out;\n}\nfunction renderPatterns(which){const d=defs[which],c=cached[which];if(!c||!c.pixels)return;\n const output=ensurePatternCanvas(which),ctx=output.getContext('2d');ctx.clearRect(0,0,output.width,output.height);\n const w=d.w,h=d.h;\n for(const key of PATTERN_KEYS[which]){\n  const p=resolvedPattern(which,key),src=patternImages[p.id],mask=patternMask(which,key);\n  if(!src||!mask||p.intensity<=0)continue;\n  const temp=document.createElement('canvas');temp.width=w;temp.height=h;const t=temp.getContext('2d',{willReadFrequently:true});\n  const halves=[{x0:0,x1:Math.floor(w/2)},{x0:Math.floor(w/2),x1:w}];\n  const regions=[];\n  for(const part of halves){let minX=w,minY=h,maxX=-1,maxY=-1;\n   for(let y=0;y<h;y+=2)for(let x=part.x0;x<part.x1;x+=2)if(mask[(y*w+x)*4+3]>100){minX=Math.min(minX,x);maxX=Math.max(maxX,x);minY=Math.min(minY,y);maxY=Math.max(maxY,y)}\n   if(maxX>=0)regions.push({minX,minY,maxX,maxY,x0:part.x0,x1:part.x1});\n  }\n  if(!regions.length)continue;\n  const baseSize=Math.max(...regions.map(r=>Math.max(r.maxX-r.minX+2,r.maxY-r.minY+2)))+8;\n  const level=Math.max(0,Math.min(10,Number(p.size)||0));\n  const minScale=.52,maxScale=which==='short'?3.6:3.2;\n  const size=baseSize*(minScale+((maxScale-minScale)/10)*level);\n  for(let idx=0;idx<regions.length;idx++){const r=regions[idx],cx=(r.minX+r.maxX)/2+(Number(p.x)||0),cy=(r.minY+r.maxY)/2+(Number(p.y)||0);\n   t.save();t.beginPath();t.rect(r.x0,0,r.x1-r.x0,h);t.clip();t.drawImage(src,cx-size/2,cy-size/2,size,size);t.restore();\n  }\n  const data=t.getImageData(0,0,w,h),a=data.data;const edge=applyHalfMoonExclusion(insetPatternAlpha(which,key,mask,w,h),which,key,w,h);\n  const solid=p.mode==='solid';\n  const [cr,cg,cb]=solid?hexrgb(p.color||'#082240'):[0,0,0];\n  for(let i=0,j=0;i<a.length;i+=4,j++){\n   if(!edge[j]){a[i+3]=0;continue;}\n   const gray=(a[i]+a[i+1]+a[i+2])/3;\n   const pigment=Math.max(0,Math.min(1,(245-gray)/205));\n   const ink=(p.intensity/10)*pigment*(edge[j]/255)*(solid ? .98 : .90);\n   // Fold gradients must modulate the sublimation, rather than the ink flattening the garment shading.\n   const sr=c.pixels.data[j],sg=c.pixels.data[j+1],sb=c.pixels.data[j+2];\n   const sourceBrightness=(sr+sg+sb)/3;\n   const shadow=Math.max(.50,Math.min(1.10,.65+sourceBrightness/320));\n   a[i]=solid?cr:0;a[i+1]=solid?cg:0;a[i+2]=solid?cb:0;a[i+3]=Math.round(255*ink*(solid?1:shadow));\n  }\n  t.putImageData(data,0,0);ctx.drawImage(temp,Math.round(d.x),Math.round(d.y));\n }\n}\nfunction stepperControl(title, initial, min, max, display, onUpdate){\n const row=document.createElement('div');row.className='compact-stepper';\n const label=document.createElement('span');label.className='stepper-label';label.textContent=title;\n const actions=document.createElement('div');actions.className='stepper-actions';\n const left=document.createElement('button');left.type='button';left.className='stepper-arrow';left.textContent='‹';left.setAttribute('aria-label','Previous '+title);\n const val=document.createElement('span');val.className='stepper-number';\n const right=document.createElement('button');right.type='button';right.className='stepper-arrow';right.textContent='›';right.setAttribute('aria-label','Next '+title);\n let value=Number(initial)||0;const show=()=>{val.textContent=display(value);left.disabled=value<=min;right.disabled=value>=max};\n left.onclick=()=>{value=Math.max(min,value-1);onUpdate(value);show()};right.onclick=()=>{value=Math.min(max,value+1);onUpdate(value);show()};show();actions.append(left,val,right);row.append(label,actions);return row;\n}\nconst V55_MACROS=[['data:image/jpeg;base64,', 'data:image/png;base64,'], ['data:image/jpeg;base64,', 'data:image/png;base64,'], ['data:image/jpeg;base64,";